import{_ as e,c as t,o as r,ag as l}from"./chunks/framework.S-Qvb3wi.js";const c=JSON.parse('{"title":"数据结构三要素","titleTemplate":"408数据结构","description":"数据结构三要素","frontmatter":{"title":"数据结构三要素","titleTemplate":"408数据结构","description":"数据结构三要素","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":{"text":"基本概念和术语","link":"/408_DS/01/408_DS_1"},"next":{"text":"习题","link":"/408_DS/01/408_DS_3"}},"headers":[],"relativePath":"408_DS/01/408_DS_2.md","filePath":"408_DS/01/408_DS_2.md","lastUpdated":null}'),o={name:"408_DS/01/408_DS_2.md"};function i(n,a,d,h,s,_){return r(),t("div",null,a[0]||(a[0]=[l('<h1 id="数据结构三要素" tabindex="-1">数据结构三要素 <a class="header-anchor" href="#数据结构三要素" aria-label="Permalink to &quot;数据结构三要素&quot;">​</a></h1><h2 id="数据的逻辑结构" tabindex="-1">数据的逻辑结构 <a class="header-anchor" href="#数据的逻辑结构" aria-label="Permalink to &quot;数据的逻辑结构&quot;">​</a></h2><p>逻辑结构是指数据元素之间的逻辑关系，即从逻辑关系上描述数据。它与数据的存储无关，是独立于计算机的。数据的逻辑结构分为线性结构和非线性结构，线性表是典型的线性结构；集合、树和图是典型的非线性结构。数据的逻辑结构分类如图所示。</p><p>1）集合。结构中的数据元素之间除＂同属一个集合＂外，别无其他关系。 2）线性结构。结构中的数据元素之间只存在一对一的关系。 3）树形结构。结构中的数据元素之间存在一对多的关系。 图状结构或网状结构。结构中的数据元素之间存在多对多的关系，如图 1．2（d）所示。</p><h2 id="数据的存储结构" tabindex="-1">数据的存储结构 <a class="header-anchor" href="#数据的存储结构" aria-label="Permalink to &quot;数据的存储结构&quot;">​</a></h2><p>存储结构是指数据结构在计算机中的表示（也称映像），也称物理结构。</p><p>它包括数据元素的表示和关系的表示。数据的存储结构是用计算机语言实现的逻辑结构，它依赖于计算机语言。</p><h3 id="顺序存储" tabindex="-1">顺序存储 <a class="header-anchor" href="#顺序存储" aria-label="Permalink to &quot;顺序存储&quot;">​</a></h3><p>把逻辑上相邻的元素存储在物理位置上也相邻的存储单元中，元素之间的关系由存储单元的邻接关系来体现。其优点是可以实现随机存取，每个元素占用最少的存储空间；缺点是只能使用相邻的一整块存储单元，因此可能产生较多的外部碎片。</p><h3 id="链式存储" tabindex="-1">链式存储 <a class="header-anchor" href="#链式存储" aria-label="Permalink to &quot;链式存储&quot;">​</a></h3><p>不要求逻辑上相邻的元素在物理位置上也相邻，借助指示元素存储地址的指针来表示元素之间的逻辑关系。其优点是不会出现碎片现象，能充分利用所有存储单元；缺点是每个元素因存储指针而占用额外的存储空间，且只能实现顺序存取。</p><h3 id="索引存储" tabindex="-1">索引存储 <a class="header-anchor" href="#索引存储" aria-label="Permalink to &quot;索引存储&quot;">​</a></h3><p>在存储元素信息的同时，还建立附加的索引表。索引表中的每项称为索引项，索引项的一般形式是（关键字，地址）。其优点是检索速度快；缺点是附加的索引表额外占用存储空间。另外，增加和删除数据时也要修改索引表，因而会花费较多的时间。</p><h3 id="散列存储" tabindex="-1">散列存储 <a class="header-anchor" href="#散列存储" aria-label="Permalink to &quot;散列存储&quot;">​</a></h3><p>根据元素的关键字直接计算出该元素的存储地址，也称哈希（Hash）存储。其优点是检索、增加和删除结点的操作都很快；缺点是若散列函数不好，则可能出现元素存储单元的冲突，而解决冲突会增加时间和空间开销。</p><h2 id="数据的运算" tabindex="-1">数据的运算 <a class="header-anchor" href="#数据的运算" aria-label="Permalink to &quot;数据的运算&quot;">​</a></h2><p>施加在数据上的运算包括运算的定义和实现。运算的定义是针对逻辑结构的，指出运算的功能；运算的实现是针对存储结构的，指出运算的具体操作步骤。</p>',17)]))}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
